import numpy as np
def equation(t, x, v, params):
    w = params[0]
    poly = (params[1] + params[2]*x + params[3]*v + params[4]*x**2 + params[5]*x*v + params[6]*v**2
            + params[7]*x**3 + params[8]*x**2*v + params[9]*x*v**2)
    return poly + 0*t + 3.0*np.cos(w*t) + 0.0*np.sin(w*t)
